return items.map(({ json }) => {
  const skillPoints = Math.min(json.skills.length * 15, 45);
  const experiencePoints = Math.min(json.yearsExperience * 12, 30);
  const portfolioPoints = json.portfolio ? 15 : 0;
  const communicationPoints = json.communication === 'strong' ? 10 : 0;
  const score = skillPoints + experiencePoints + portfolioPoints + communicationPoints;

  return {
    json: {
      ...json,
      score,
      reasoning: `Skills ${skillPoints}/45 · experience ${experiencePoints}/30 · portfolio ${portfolioPoints}/15 · communication ${communicationPoints}/10`
    }
  };
});

